 internal sealed class UndoTransactionsWindow:Window {
  internal readonly ListView Transactions=new ListView();internal readonly Button UndoButton;readonly TextBox details=new TextBox{IsReadOnly=true,AcceptsReturn=true,TextWrapping=TextWrapping.Wrap,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};readonly TextBlock status=CopyUi.Label("");
  readonly Func<UndoHistoryEntry[]> snapshot;readonly Func<bool> canRun;readonly Action<bool> activity;readonly Action refreshed;readonly DispatcherTimer timer=new DispatcherTimer{Interval=TimeSpan.FromSeconds(3)};CancellationTokenSource cancellation=new CancellationTokenSource();bool refreshing,applying,closed;internal Task RefreshTask;
  internal UndoTransactionsWindow(Window owner,Func<UndoHistoryEntry[]> entries,Func<bool> allowed,Action<bool> change,Action refresh){
   snapshot=entries;canRun=allowed;activity=change;refreshed=refresh;CopyUi.Style(this,owner,L.Text("undoHistory.title"),1120);Height=740;MinHeight=500;MinWidth=820;ResizeMode=ResizeMode.CanResize;SizeToContent=SizeToContent.Manual;
   var body=new DockPanel();CopyUi.SectionedSurface(this,body);var legend=CopyUi.Label(L.Text("undoHistory.legend"));DockPanel.SetDock(legend,Dock.Top);body.Children.Add(legend);
   var buttons=new WrapPanel();DockPanel.SetDock(buttons,Dock.Bottom);body.Children.Add(buttons);DockPanel.SetDock(status,Dock.Bottom);body.Children.Add(status);
   var grid=new Grid();grid.RowDefinitions.Add(new RowDefinition{Height=new GridLength(1,GridUnitType.Star)});grid.RowDefinitions.Add(new RowDefinition{Height=new GridLength(6)});grid.RowDefinitions.Add(new RowDefinition{Height=new GridLength(.65,GridUnitType.Star)});body.Children.Add(grid);grid.Children.Add(Transactions);Grid.SetRow(details,2);grid.Children.Add(details);var splitter=new GridSplitter{Height=6,HorizontalAlignment=HorizontalAlignment.Stretch};Grid.SetRow(splitter,1);grid.Children.Add(splitter);
   var columns=new GridView();foreach(var c in new[]{new[]{"undoHistory.time","When","145"},new[]{"undoHistory.operation","Title","245"},new[]{"common.status","Status","170"},new[]{"undoHistory.steps","Count","70"},new[]{"undoHistory.reason","Reason","460"}})columns.Columns.Add(new GridViewColumn{Header=L.Text(c[0]),DisplayMemberBinding=new Binding(c[1]),Width=Double.Parse(c[2])});Transactions.View=columns;
   var style=new Style(typeof(ListViewItem));style.Setters.Add(new Setter(Control.BackgroundProperty,new Binding("Tint")));style.Setters.Add(new Setter(Control.ForegroundProperty,new Binding("Ink")));style.Setters.Add(new Setter(Control.PaddingProperty,new Thickness(4,6,4,6)));Transactions.ItemContainerStyle=style;
   UndoButton=CopyUi.Button(L.Text("undoHistory.undoSelected"),async delegate{await UndoSelected();});UndoButton.IsEnabled=false;buttons.Children.Add(UndoButton);buttons.Children.Add(CopyUi.Button(L.Text("action.refresh"),delegate{RefreshTask=RefreshRows();}));buttons.Children.Add(CopyUi.Button(L.Text("action.close"),Close));
   Transactions.SelectionChanged+=delegate{UpdateSelection();};timer.Tick+=delegate{RefreshTask=RefreshRows();};Loaded+=delegate{RefreshTask=RefreshRows();timer.Start();};Closing+=delegate(object sender,System.ComponentModel.CancelEventArgs e){if(applying){e.Cancel=true;cancellation.Cancel();return;}closed=true;cancellation.Cancel();timer.Stop();};
  }
  async Task RefreshRows(){if(refreshing||applying||closed)return;refreshing=true;var selected=Transactions.SelectedItem as UndoHistoryEntry;var rows=snapshot();status.Text=L.Text("undoHistory.checking");
   try{await Task.Run(()=>{foreach(var row in rows){cancellation.Token.ThrowIfCancellationRequested();if(row.Group!=null){if(!SafeUndo.Groups().Contains(row.Group)){row.Reason=L.Text("undoHistory.expired");}else if(row.Group.Items.Count==0){row.Status=L.Text(row.Unsupported>0?"undoHistory.partlyDone":"undoHistory.done");row.Reason=L.Text(row.Unsupported>0?"undoHistory.unsupportedSteps":"undoHistory.alreadyUndone");}else{row.Inspection=UndoEligibility.Inspect(row.Group,false,cancellation.Token);row.Count=row.Inspection.Available.Count+" / "+(row.Inspection.Total+row.Unsupported);row.FullReason=(row.Unsupported>0?L.Format("undoHistory.unsupportedCount",row.Unsupported)+"\n":"")+String.Join("\n",row.Inspection.Problems);row.Reason=row.Unsupported>0?L.Format("undoHistory.unsupportedCount",row.Unsupported):(row.Inspection.Problems.Count==0?"":row.Inspection.Problems[0].Split('\n').Last());}}}});
    if(closed)return;foreach(var row in rows){int available=row.Inspection==null?0:row.Inspection.Available.Count;if(available>0){row.Status=L.Text(available==row.Inspection.Total&&row.Unsupported==0?"undoHistory.available":"undoHistory.partial");row.Tint=new SolidColorBrush(Color.FromArgb(40,(byte)(available==row.Inspection.Total&&row.Unsupported==0?20:220),(byte)(available==row.Inspection.Total&&row.Unsupported==0?170:150),55));row.Ink=FluentTheme.Text;}else{if(String.IsNullOrEmpty(row.Status))row.Status=L.Text("undoHistory.unavailable");row.Tint=new SolidColorBrush(Color.FromArgb(22,110,110,110));row.Ink=FluentTheme.Muted;}}
