   }catch(OperationCanceledException){}catch(Exception ex){if(!closed)status.Text=ex.Message;}finally{refreshing=false;}
  }
  void UpdateSelection(){var row=Transactions.SelectedItem as UndoHistoryEntry;UndoButton.IsEnabled=!applying&&row!=null&&row.Inspection!=null&&row.Inspection.Available.Count>0&&canRun();UndoButton.Content=L.Text(row!=null&&row.Inspection!=null&&(row.Inspection.Available.Count<row.Inspection.Total||row.Unsupported>0)?"undoHistory.undoAvailable":"undoHistory.undoSelected");details.Text=row==null?"":row.Title+"\n"+row.Status+"\n"+(row.FullReason??row.Reason)+"\n\n"+(row.Group==null?(row.Record==null?"":OperationJournal.Log(new[]{row.Record})):String.Join("\n",(row.Group.OriginalItems??row.Group.Items).Select(x=>(x.Move?x.Target+" → "+x.Source:L.Text("undoHistory.removeCopy")+" "+x.Target))))+"\n\n"+(row!=null&&row.Record!=null&&row.Group!=null?OperationJournal.Log(new[]{row.Record}):"");}
  async Task UndoSelected(){var row=Transactions.SelectedItem as UndoHistoryEntry;if(row==null||row.Group==null||!canRun()||applying||refreshing)return;applying=true;timer.Stop();UndoButton.IsEnabled=false;activity(true);
   try{var verified=await Task.Run(()=>UndoEligibility.Inspect(row.Group,true,cancellation.Token));if(verified.Available.Count==0){status.Text=String.Join("\n",verified.Problems);return;}
    string message=L.Format("undoHistory.confirm",verified.Available.Count,verified.Total+row.Unsupported)+"\n\n"+String.Join("\n",verified.Available.Take(20).Select(x=>x.Move?x.Target+" → "+x.Source:x.Target));if(MessageBox.Show(this,message,L.Text("undoHistory.title"),MessageBoxButton.YesNo,MessageBoxImage.Question)!=MessageBoxResult.Yes)return;
    await Task.Run(()=>UndoEligibility.ApplyAvailable(row.Group,verified.Available.ToArray(),cancellation.Token));status.Text=L.Text("state.completed");
   }catch(OperationCanceledException){status.Text=L.Text("mediaNames.cancelled");}catch(Exception ex){MessageBox.Show(this,ex.Message,L.Text("undoHistory.title"));}finally{activity(false);applying=false;refreshed();if(cancellation.IsCancellationRequested){cancellation.Dispose();cancellation=new CancellationTokenSource();}RefreshTask=RefreshRows();timer.Start();}
  }
 }
 public partial class MainWindow {
  UndoTransactionsWindow undoTransactionsWindow;
  void RecordUndoTransaction(string title,IEnumerable<UndoReceipt> receipts){var group=SafeUndo.Record(title,receipts);if(group==null)return;var record=new OperationRecord{Title=title,State=L.Code("state.completed"),Ended=DateTime.Now,Undo=group,Items=group.Items.Select(x=>new OperationItem{Source=x.Source,Target=x.Target,Directory=x.Directory,State=L.Code("state.completed")}).ToList()};operationJournal.Records.Insert(0,record);operationJournal.Save();}
  static int UnsupportedUndoSteps(OperationRecord record){if(record.Undo==null)return 0;var receipts=record.Undo.OriginalItems??record.Undo.Items;return record.Items.Count(item=>!item.Directory&&!String.IsNullOrEmpty(item.Target)&&item.State==L.Code("state.completed")&&!receipts.Any(r=>String.Equals(r.Target,item.Target,StringComparison.OrdinalIgnoreCase)||(r.Move&&r.Directory&&item.Target.StartsWith(r.Target.TrimEnd('\\')+"\\",StringComparison.OrdinalIgnoreCase))));}
  internal UndoHistoryEntry[] UndoTransactions(){var groups=SafeUndo.Groups();var records=operationJournal.Records.Take(300).Concat(operationJournal.Records.Skip(300).Where(r=>r.Undo!=null&&groups.Contains(r.Undo))).ToArray();return records.Select(record=>new UndoHistoryEntry{When=record.Started.ToString("dd.MM. HH:mm:ss"),Title=record.Title,Record=record,Group=record.Undo,Unsupported=UnsupportedUndoSteps(record),Reason=record.Undo==null?L.Text("undoHistory.noReceipt"):""}).Concat(groups.Where(g=>!records.Any(r=>Object.ReferenceEquals(r.Undo,g))).Select(g=>new UndoHistoryEntry{When=g.Created.ToString("dd.MM. HH:mm:ss"),Title=g.Title,Group=g})).OrderByDescending(x=>x.Record==null?x.Group.Created:x.Record.Started).ToArray();}
  void OpenUndoTransactions(){if(undoTransactionsWindow!=null){undoTransactionsWindow.Activate();return;}undoTransactionsWindow=new UndoTransactionsWindow(this,UndoTransactions,delegate{return !busy&&!copyRunning&&fileToolsRunning==0&&deletions==0&&networkCopies==0&&archiveOperations==0;},value=>busy=value,delegate{left.Refresh();right.Refresh();operationJournal.Save();});undoTransactionsWindow.Closed+=delegate{undoTransactionsWindow=null;};undoTransactionsWindow.Show();}
 }
